svg.script:
/*  */
(function() {
  // 5 Target Data Store with Medical Accuracy
  var targetsData = [
    {
      id: 1,
      ring: 1,
      name: "ALVO 1: PROMONTÓRIO SACRAL (S1)",
      aroTag: "ARO SUPERIOR (ENTRADA)",
      stepBadge: "PASSO 1 DE 5 · ARO 1: ENTRADA",
      question: "Maneira de palpação: Dedo examinador alcança o promontório sacral?",
      normal: {
        val: "Conjugada Diagonal > 11,5 cm",
        status: "NORMAL / BACIA FAVORÁVEL",
        desc: "Promontório NÃO atingível com o dedo examinador médio de comprimento padrão (~12 cm). A parede sacral anterior permanece distante.",
        impact: "Estreito superior amplo (≥10,5 cm obstétrica). Permite a insinuação do polo cefálico sem impedimento no aro de entrada.",
        range: "Faixa Normal: Conjugada Diagonal > 11,5 cm (Obstétrica > 10,5 cm)",
        aroTitle: "Aro 1 (Entrada) = Insinuação Cefálica",
        aroBody: "Se o promontório for facilmente tocado, a Conjugada Diagonal é menor que 11,5 cm, indicando Estreitamento da Entrada Pelvina.",
        aroRule: "Regra Prática: Promontório inatingível = Aro 1 Aprovado."
      },
      altered: {
        val: "Conjugada Diagonal < 11,5 cm",
        status: "ALTERADO / ESTREITAMENTO",
        desc: "Promontório FACILMENTE atingido com o dedo examinador. Medida da Conjugada Diagonal reduzida (< 11,5 cm).",
        impact: "Redução da Conjugada Obstétrica (< 10,5 cm). Risco elevado de vício de insinuação ou parada alta no aro de entrada.",
        range: "Achado Patológico: Conjugada Diagonal < 11,5 cm (Achatamento Anteroposterior)",
        aroTitle: "Aro 1 (Entrada) = Vício de Entrada / Platipeloide",
        aroBody: "O achado de promontório atingível é característico da bacia platipeloide ou androide estreitada na entrada.",
        aroRule: "Regra Prática: Promontório atingível = Estreitamento de Entrada."
      }
    },
    {
      id: 2,
      ring: 2,
      name: "ALVO 2: ESPINHAS ISQUIÁTICAS",
      aroTag: "ARO MÉDIO (MEIO)",
      stepBadge: "PASSO 2 DE 5 · ARO 2: MEIO PELVINO",
      question: "Maneira de palpação: As espinhas isquiáticas são salientes ou rombas?",
      normal: {
        val: "Diâmetro Interespinha ≥ 10,0 cm",
        status: "NORMAL / BACIA FAVORÁVEL",
        desc: "Espinhas isquiáticas rombas, apagadas e pouco salientes à palpação vaginal lateral bilateral.",
        impact: "Estreito médio amplo. O diâmetro bi-espinha (interespinha) ≥ 10 cm permite rotação interna da cabeça fetal sem obstáculo.",
        range: "Faixa Normal: Espinhas rombas e Diâmetro Interespinha ≥ 10,0 cm",
        aroTitle: "Aro 2 (Meio) = Rotação Interna Cefálica",
        aroBody: "As espinhas isquiáticas delimitam o plano de menor diâmetro da bacia. Espinhas rombas garantem o trânsito do meio.",
        aroRule: "Regra Prática: Espinhas rombas = Aro 2 Adequado."
      },
      altered: {
        val: "Diâmetro Interespinha < 9.5 cm",
        status: "ALTERADO / ESTREITAMENTO",
        desc: "Espinhas isquiáticas muito proeminentes, pontiagudas (bicornes) e convergentes para a cavidade.",
        impact: "Estreitamento do plano médio pelvino (< 9.5 cm). Risco de parada de progressão em variedade transversa (parada de rotação).",
        range: "Achado Patológico: Espinhas proeminentes e Diâmetro Interespinha < 9,5 cm",
        aroTitle: "Aro 2 (Meio) = Estreitamento do Plano Médio",
        aroBody: "Espinhas proeminentes reduzem o espaço de rotação cefálica, frequente em bacias androides e antropoides.",
        aroRule: "Regra Prática: Espinhas proeminentes = Estreitamento do Meio."
      }
    },
    {
      id: 3,
      ring: 2,
      name: "ALVO 3: CONCAVIDADE SACRAL",
      aroTag: "ARO MÉDIO (MEIO)",
      stepBadge: "PASSO 3 DE 5 · ARO 2: MEIO PELVINO",
      question: "Maneira de palpação: A curvatura e concavidade do sacro estão preservadas?",
      normal: {
        val: "Sacro Cavado e Bem Curvo",
        status: "NORMAL / BACIA FAVORÁVEL",
        desc: "Sacro bem escavado à palpação longitudinal (concavidade harmoniosa de S1 a S5 com mobilidade coccígea).",
        impact: "Oferece amplitude de profundidade anteroposterior no plano médio, facilitando a descida com flexão adequada.",
        range: "Faixa Normal: Concavidade sacral bem amoldada e profunda",
        aroTitle: "Aro 2 (Meio) = Amplitude Anteroposterior Médio",
        aroBody: "A curvatura sacral fisiológica amplia a escavação pélvica necessária para acomodar o diâmetro suboccipitobregmático.",
        aroRule: "Regra Prática: Sacro cavado = Meio amplo."
      },
      altered: {
        val: "Sacro Plano / Retificado",
        status: "ALTERADO / ESTREITAMENTO",
        desc: "Sacro plano, verticalizado, reto ou projetado para a frente ('sacro em lama'), reduzindo o espaço posterior.",
        impact: "Diminuição acentuada da profundidade do diâmetro sagital do meio pélvico, impedindo a acomodação fetal.",
        range: "Achado Patológico: Retificação sacral ou projeção anterior de S3-S5",
        aroTitle: "Aro 2 (Meio) = Achatamento da Escavação",
        aroBody: "O sacro reto limita a escavação sacral, forçando a cabeça fetal contra o arco púbico anterior.",
        aroRule: "Regra Prática: Sacro plano = Redução da concavidade sacral."
      }
    },
    {
      id: 4,
      ring: 3,
      name: "ALVO 4: ÂNGULO SUBPÚBICO",
      aroTag: "ARO INFERIOR (SAÍDA)",
      stepBadge: "PASSO 4 DE 5 · ARO 3: SAÍDA PELVINA",
      question: "Maneira de palpação: Ângulo subpúbico é obtuso (≥ 90°) sob a sínfise?",
      normal: {
        val: "Ângulo Subpúbico ≥ 90° (Obtuso)",
        status: "NORMAL / BACIA FAVORÁVEL",
        desc: "Arco subpúbico amplo e arredondado. Acomoda facilmente dois dedos examinadores abertos sob a sínfise púbica.",
        impact: "Aro de saída amplo. Permite a deflexão e o desprendimento do polo cefálico sob a sínfise sem trauma perineal excessivo.",
        range: "Faixa Normal: Ângulo Subpúbico ≥ 90° (Ginecoide / Formato em U)",
        aroTitle: "Aro 3 (Saída) = Desprendimento Cefálico",
        aroBody: "O ângulo obtuso permite que a cabeça fetal se apoie suavemente sob a sínfise durante o desprendimento.",
        aroRule: "Regra Prática: Ângulo obtuso (≥90°) = Aro 3 Aprovado."
      },
      altered: {
        val: "Ângulo Subpúbico < 90° (Agudo)",
        status: "ALTERADO / ESTREITAMENTO",
        desc: "Arco subpúbico estreito, agudo e em formato de 'V' fechado, não acomodando os dedos abertos.",
        impact: "Força o polo cefálico para trás contra o períneo posterior, aumentando drasticamente o risco de laceração perineal de 3º/4º grau ou distocia.",
        range: "Achado Patológico: Ângulo Subpúbico < 90° (Androide / Formato em V)",
        aroTitle: "Aro 3 (Saída) = Estreitamento de Arco Subpúbico",
        aroBody: "Um ângulo agudo projeta o ponto de desprendimento para baixo e para trás, empurrando o polo fetal contra o coccix.",
        aroRule: "Regra Prática: Ângulo agudo = Estreitamento de Saída."
      }
    },
    {
      id: 5,
      ring: 3,
      name: "ALVO 5: TUBEROSIDADES ISQUIÁTICAS",
      aroTag: "ARO INFERIOR (SAÍDA)",
      stepBadge: "PASSO 5 DE 5 · ARO 3: SAÍDA PELVINA",
      question: "Maneira de palpação: O punho fechado examinador cabe entre as tuberosidades?",
      normal: {
        val: "Diâmetro Intertuberoso ≥ 8,5 - 10 cm",
        status: "NORMAL / BACIA FAVORÁVEL",
        desc: "O punho fechado do examinador (manobra de Osiander/De Lee) entra confortavelmente entre as tuberosidades isquiáticas.",
        impact: "Diâmetro bi-isquiático transverso amplo. Garante a saída definitiva do diâmetro biparietal fetal.",
        range: "Faixa Normal: Diâmetro Intertuberoso ≥ 8,5 - 10,0 cm (Punho cabe)",
        aroTitle: "Aro 3 (Saída) = Diâmetro Transverso da Saída",
        aroBody: "A passagem do punho fechado confirma que o diâmetro intertuberoso de saída não está comprimido.",
        aroRule: "Regra Prática: Punho cabe = Saída Pelvina Adequada."
      },
      altered: {
        val: "Diâmetro Intertuberoso < 8,5 cm",
        status: "ALTERADO / ESTREITAMENTO",
        desc: "O punho fechado do examinador NÃO consegue ser introduzido entre as tuberosidades isquiáticas.",
        impact: "Estreitamento severo do diâmetro de saída. Impede o desprendimento normal do feto, requerendo conduta de alerta.",
        range: "Achado Patológico: Diâmetro Intertuberoso < 8,5 cm (Punho não cabe)",
        aroTitle: "Aro 3 (Saída) = Estreitamento Bi-isquiático",
        aroBody: "Achado típico de bacias funiliformes / androides com afunilamento inferior acentuado.",
        aroRule: "Regra Prática: Punho não cabe = Estreitamento de Saída."
      }
    }
  ];

  // State variables
  var currentTargetId = 1;
  var currentFinding = "normal"; // "normal" or "altered"
  var isTourRunning = false;
  var tourInterval = null;

  // DOM Elements
  var panelStepBadge = document.getElementById("a12p13h-panel-step-badge");
  var panelAroTag = document.getElementById("a12p13h-panel-aro-tag");
  var panelTargetTitle = document.getElementById("a12p13h-panel-target-title");
  var panelQuestion = document.getElementById("a12p13h-panel-question");

  var btnSimNormal = document.getElementById("a12p13h-btn-sim-normal");
  var btnSimAltered = document.getElementById("a12p13h-btn-sim-altered");

  var findingCardBg = document.getElementById("a12p13h-finding-card-bg");
  var statusTagBg = document.getElementById("a12p13h-status-tag-bg");
  var statusTagText = document.getElementById("a12p13h-status-tag-text");
  var findingVal = document.getElementById("a12p13h-finding-val");
  var findingDesc = document.getElementById("a12p13h-finding-desc");
  var findingImpact = document.getElementById("a12p13h-finding-impact");
  var rangeBox = document.getElementById("a12p13h-range-box");
  var rangeText = document.getElementById("a12p13h-range-text");
  var cardDivider = document.getElementById("a12p13h-card-divider");

  var aroSummaryTitle = document.getElementById("a12p13h-aro-summary-title");
  var aroSummaryBody = document.getElementById("a12p13h-aro-summary-body");
  var aroSummaryRule = document.getElementById("a12p13h-aro-summary-rule");

  var btnPrev = document.getElementById("a12p13h-btn-prev");
  var btnNext = document.getElementById("a12p13h-btn-next");
  var btnTour = document.getElementById("a12p13h-btn-tour");
  var tourBtnText = document.getElementById("a12p13h-tour-btn-text");

  // Update UI Function
  function updateUI() {
    var data = targetsData[currentTargetId - 1];
    var findingData = (currentFinding === "normal") ? data.normal : data.altered;

    // Panel Text
    if (panelStepBadge) panelStepBadge.textContent = data.stepBadge;
    if (panelAroTag) panelAroTag.textContent = data.aroTag;
    if (panelTargetTitle) panelTargetTitle.textContent = data.name;
    if (panelQuestion) panelQuestion.textContent = data.question;

    // Finding Card Styling and Content
    if (currentFinding === "normal") {
      if (findingCardBg) { findingCardBg.setAttribute("fill", "#0f291e"); findingCardBg.setAttribute("stroke", "#22c55e"); }
      if (statusTagBg) findingStatusTagBg("#22c55e");
      if (statusTagText) { statusTagText.textContent = findingData.status; statusTagText.setAttribute("fill", "#ffffff"); }
      if (findingVal) { findingVal.textContent = findingData.val; findingVal.setAttribute("fill", "#4ade80"); }
      if (rangeBox) { rangeBox.setAttribute("fill", "#041f13"); rangeBox.setAttribute("stroke", "#166534"); }
      if (rangeText) { rangeText.textContent = findingData.range; rangeText.setAttribute("fill", "#86efac"); }
      if (cardDivider) cardDivider.setAttribute("stroke", "#1f4e38");

      if (btnSimNormal) btnSimNormal.classList.add("a12p13h-selected");
      if (btnSimAltered) btnSimAltered.classList.remove("a12p13h-selected");
    } else {
      if (findingCardBg) { findingCardBg.setAttribute("fill", "#2e0b0b"); findingCardBg.setAttribute("stroke", "#ef4444"); }
      if (statusTagBg) findingStatusTagBg("#ef4444");
      if (statusTagText) { statusTagText.textContent = findingData.status; statusTagText.setAttribute("fill", "#ffffff"); }
      if (findingVal) { findingVal.textContent = findingData.val; findingVal.setAttribute("fill", "#f87171"); }
      if (rangeBox) { rangeBox.setAttribute("fill", "#210505"); rangeBox.setAttribute("stroke", "#991b1b"); }
      if (rangeText) { rangeText.textContent = findingData.range; rangeText.setAttribute("fill", "#fca5a5"); }
      if (cardDivider) cardDivider.setAttribute("stroke", "#450a0a");

      if (btnSimNormal) btnSimNormal.classList.remove("a12p13h-selected");
      if (btnSimAltered) btnSimAltered.classList.add("a12p13h-selected");
    }

    function findingStatusTagBg(color) {
      statusTagBg.setAttribute("fill", color);
    }

    if (findingDesc) findingDesc.textContent = findingData.desc;
    if (findingImpact) findingImpact.textContent = findingData.impact;

    if (aroSummaryTitle) aroSummaryTitle.textContent = findingData.aroTitle;
    if (aroSummaryBody) aroSummaryBody.textContent = findingData.aroBody;
    if (aroSummaryRule) aroSummaryRule.textContent = findingData.aroRule;

    // Highlight Active Hotspots and Selector Buttons
    for (var i = 1; i <= 5; i++) {
      var pin = document.getElementById("a12p13h-hotspot-" + i);
      var card = document.getElementById("a12p13h-card-target-" + i);

      if (pin) {
        if (i === currentTargetId) pin.classList.add("a12p13h-active");
        else pin.classList.remove("a12p13h-active");
      }

      if (card) {
        if (i === currentTargetId) card.classList.add("a12p13h-active");
        else card.classList.remove("a12p13h-active");
      }
    }

    // Highlight Ring Overlay Planes
    var targetRing = data.ring;
    for (var r = 1; r <= 3; r++) {
      var plane = document.getElementById("a12p13h-plane-ring" + r);
      var ringNav = document.getElementById("a12p13h-ring-nav-" + r);
      if (plane) {
        if (r === targetRing) plane.classList.add("a12p13h-active");
        else plane.classList.remove("a12p13h-active");
      }
      if (ringNav) {
        if (r === targetRing) ringNav.classList.add("a12p13h-active");
        else ringNav.classList.remove("a12p13h-active");
      }
    }
  }

  // Event Binding Helper
  function bindClick(id, handler) {
    var el = document.getElementById(id);
    if (el) {
      el.addEventListener("click", handler);
      el.addEventListener("keydown", function(e) {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          handler();
        }
      });
    }
  }

  // Bind Hotspots 1..5 and Cards 1..5
  for (var i = 1; i <= 5; i++) {
    (function(id) {
      bindClick("a12p13h-hotspot-" + id, function() {
        currentTargetId = id;
        stopTour();
        updateUI();
      });
      bindClick("a12p13h-card-target-" + id, function() {
        currentTargetId = id;
        stopTour();
        updateUI();
      });
    })(i);
  }

  // Bind Ring Nav 1..3
  bindClick("a12p13h-ring-nav-1", function() { currentTargetId = 1; stopTour(); updateUI(); });
  bindClick("a12p13h-ring-nav-2", function() { currentTargetId = 2; stopTour(); updateUI(); });
  bindClick("a12p13h-ring-nav-3", function() { currentTargetId = 4; stopTour(); updateUI(); });

  // Bind Simulator Buttons
  bindClick("a12p13h-btn-sim-normal", function() {
    currentFinding = "normal";
    updateUI();
  });
  bindClick("a12p13h-btn-sim-altered", function() {
    currentFinding = "altered";
    updateUI();
  });

  // Bind Prev / Next
  bindClick("a12p13h-btn-prev", function() {
    currentTargetId = (currentTargetId > 1) ? currentTargetId - 1 : 5;
    stopTour();
    updateUI();
  });
  bindClick("a12p13h-btn-next", function() {
    currentTargetId = (currentTargetId < 5) ? currentTargetId + 1 : 1;
    stopTour();
    updateUI();
  });

  // Guided Tour Mechanism
  function stopTour() {
    if (isTourRunning) {
      isTourRunning = false;
      clearInterval(tourInterval);
      if (tourBtnText) tourBtnText.textContent = "PERCURSO GUIADO";
    }
  }

  bindClick("a12p13h-btn-tour", function() {
    if (isTourRunning) {
      stopTour();
    } else {
      isTourRunning = true;
      if (tourBtnText) tourBtnText.textContent = "PARAR PERCURSO";
      tourInterval = setInterval(function() {
        currentTargetId = (currentTargetId < 5) ? currentTargetId + 1 : 1;
        updateUI();
      }, 3000);
    }
  });

  // Initial Render
  updateUI();
})();
/*  */
